SELECT [Gesamt Normierung Zeitraum].Elektrolyseur, [Gesamt Normierung Zeitraum].Position, qryCEAlleElementeNaOH.Bezeichnung, [Gesamt Normierung Zeitraum].Datum, [Gesamt Normierung Zeitraum].i, SPCBer([Gesamt Normierung Zeitraum]![Un],[qryCEAlleElementeNaOH]![CE]) AS Energieverbrauch, [Gesamt Normierung Zeitraum].Un, GetGewIRef() AS iRefSPC
FROM [Gesamt Normierung Zeitraum] INNER JOIN qryCEAlleElementeNaOH ON ([Gesamt Normierung Zeitraum].Position = qryCEAlleElementeNaOH.Position) AND ([Gesamt Normierung Zeitraum].Datum = qryCEAlleElementeNaOH.Datum) AND ([Gesamt Normierung Zeitraum].Elektrolyseur = qryCEAlleElementeNaOH.Elektrolyseur);
